// The committed dev-city world: generated by src/render/tools/build-dev-city.ts, loaded by
// the sim (colliders) and the renderer (glb tiles, plus one collider-only tile).
import { NodeIO } from "@gltf-transform/core";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { COLLIDER_ONLY_TILE, generate } from "../../src/render/tools/build-dev-city.ts";
import { KHRMeshQuantization } from "../../src/render/tools/glb.ts";
import { pointInPolygon, step, createInitialState } from "../../src/sim/index.ts";
import type { Manifest, RoadGraph } from "../../src/render/types.ts";
import { ROOT, loadWorld, readJson } from "../helpers.ts";

const DIR = "public/tiles/dev-city";
const manifest = readJson<Manifest>(`${DIR}/manifest.json`);

describe("dev-city", () => {
  it("is what the generator produces (run node src/render/tools/build-dev-city.ts after changing it)", async () => {
    const { files } = await generate();
    expect([...files.keys()].sort()).toEqual(
      [...new Set([...manifest.tiles.flatMap((t) => [t.collider, t.glb ?? []].flat()), "manifest.json", "roads.json"])].sort(),
    );
    for (const [name, data] of files) {
      const disk = readFileSync(join(ROOT, DIR, name));
      const want = typeof data === "string" ? Buffer.from(data, "utf8") : Buffer.from(data);
      expect(disk.equals(want), name).toBe(true);
    }
  }, 60_000);

  it("is a few hundred buildings or more over a street grid, slope and waterfront", () => {
    const { world } = loadWorld("dev-city");
    const buildings = world.tiles.reduce((s, t) => s + t.buildings.length, 0);
    expect(buildings).toBeGreaterThan(300);
    expect(manifest.tiles.length).toBeGreaterThanOrEqual(20);
    const heights = world.tiles.flatMap((t) => t.ground?.heights ?? []);
    expect(Math.max(...heights)).toBeGreaterThan(60); // hills
    expect(Math.min(...heights)).toBeLessThan(-2); // the Bay floor
    const roads = readJson<RoadGraph>(`${DIR}/roads.json`);
    expect(roads.edges.length).toBeGreaterThan(200);
  });

  it("ships glb tiles for the renderer and exactly one collider-only tile", async () => {
    const io = new NodeIO().registerExtensions([KHRMeshQuantization]);
    const glbs = manifest.tiles.filter((t) => t.glb);
    expect(manifest.tiles.filter((t) => !t.glb).map((t) => t.id)).toEqual([COLLIDER_ONLY_TILE]);
    for (const t of glbs) expect(existsSync(join(ROOT, DIR, t.glb!)), t.glb!).toBe(true);
    // Spot-check one: named layers, shared material names, building ranges, quantization.
    const t = glbs.find((q) => (q.stats?.buildings ?? 0) > 100)!;
    const bytes = readFileSync(join(ROOT, DIR, t.glb!));
    const json = JSON.parse(bytes.subarray(20, 20 + bytes.readUInt32LE(12)).toString("utf8")) as { extensionsRequired?: string[] };
    expect(json.extensionsRequired).toContain("KHR_mesh_quantization");
    const doc = await io.readBinary(new Uint8Array(bytes));
    const meshes = doc.getRoot().listMeshes();
    expect(meshes.map((m) => m.getName()).sort()).toEqual(expect.arrayContaining(["buildings", "ground", "roads"]));
    const b = meshes.find((m) => m.getName() === "buildings")!.listPrimitives()[0]!;
    expect(b.getMaterial()?.getName()).toBe("building");
    expect(b.getAttribute("_FACADE")).not.toBeNull();
    expect(b.getAttribute("TEXCOORD_0")).not.toBeNull();
    const ranges = (b.getExtras() as { fcBuildings: Array<[string, number, number]> }).fcBuildings;
    expect(ranges.length).toBe(t.stats!.buildings);
  });

  it("spawns the player on open road, and the sim can drive in it", () => {
    const { world, manifest: m } = loadWorld("dev-city");
    for (const t of world.tiles) for (const b of t.buildings) expect(pointInPolygon(m.spawn.x, m.spawn.z, b.footprint), b.id).toBe(false);
    // The whole car is on the carriageway, a lane's width from the kerb: not on the kerb.
    const roads = readJson<RoadGraph>(`${DIR}/roads.json`);
    let best = { outside: Infinity, name: "" };
    for (const e of roads.edges) {
      const half = (e.widthM ?? e.lanes * 3.5) / 2;
      for (let i = 1; i < e.points.length; i++) {
        const [ax, az] = e.points[i - 1]!;
        const [bx, bz] = e.points[i]!;
        const ex = bx - ax;
        const ez = bz - az;
        const t = Math.max(0, Math.min(1, ((m.spawn.x - ax) * ex + (m.spawn.z - az) * ez) / (ex * ex + ez * ez || 1)));
        const outside = Math.hypot(m.spawn.x - ax - ex * t, m.spawn.z - az - ez * t) - half;
        if (outside < best.outside) best = { outside, name: e.name ?? e.id };
      }
    }
    expect(best.outside, `spawn distance outside ${best.name}'s carriageway, m`).toBeLessThan(-3);
    let s = createInitialState(world, 3, ["p1"], m.spawn);
    for (let i = 0; i < 300; i++) s = step(world, s, { p1: { throttle: 1, steer: 0, brake: 0, actions: 0 } });
    const car = s.players.p1!.car;
    expect(Number.isFinite(car.x) && Number.isFinite(car.z) && Number.isFinite(car.y)).toBe(true);
    expect(m.spawn.z - car.z).toBeGreaterThan(50); // drove north along the boulevard
    expect(car.y).toBeGreaterThan(1);
  });
});
